const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    const pools = lines[0]
      .split(",")
      .map((line) => line.split(":").map(Number));

    const applies = lines[1].split(",").map(Number);

    console.log(getResult(pools, applies));
    lines.length = 0;
  }
});

/**
 * @param {*} pools 内存池资源列表，是一个二维数组，元素是[内存粒度大小， 内存粒度数量]
 * @param {*} applies 申请列表
 * @returns 内存池分配结果
 */
function getResult(pools, applies) {
  pools.sort((a, b) => a[0] - b[0]);

  const ans = [];

  for (let apply of applies) {
    let idx = binarySearch(pools, apply);

    if (idx < 0) {
      idx = -idx - 1;
    }

    if (pools[idx] === undefined) {
      ans.push(false);
      continue;
    }

    pools[idx][1]--;

    ans.push(true);

    if (pools[idx][1] === 0) {
      pools.splice(idx, 1);
    }
  }

  return ans.join();
}

function binarySearch(arr, key) {
  let low = 0;
  let high = arr.length - 1;

  while (low <= high) {
    let mid = (low + high) >>> 1;
    let midVal = arr[mid][0]; // 专门用于pools二分查找的binarySearch

    if (midVal < key) {
      low = mid + 1;
    } else if (midVal > key) {
      high = mid - 1;
    } else {
      return mid;
    }
  }
  return -low - 1;
}

